"use strict";
import { useState } from "react";
import { Flex, IconButton, Input } from "ui/src";
import { Search, X } from "ui/src/components/icons";
import { useSporeColors } from "ui/src/hooks/useSporeColors";
import { zIndexes } from "ui/src/theme";
export function AnimatedSearchBar({
  value,
  onChange,
  onClear,
  placeholder = "Search...",
  height = 40,
  xAxis = "right",
  collapsedWidth = 45,
  expandedWidth = 250
}) {
  const [isOpen, setIsOpen] = useState(false);
  const colors = useSporeColors();
  const handleFocus = () => setIsOpen(true);
  const handleBlur = () => {
    if (value === "") {
      setIsOpen(false);
    }
  };
  const handleClose = () => {
    onChange("");
    if (onClear) onClear();
    setIsOpen(false);
  };
  if (value && !isOpen) {
    setIsOpen(true);
  }
  return <Flex position="relative" height={height} zIndex={zIndexes.mask}>
      <Flex height={40} width={45} />
      <Flex
    backgroundColor="$surface1"
    className="search-bar"
    right={xAxis === "right" ? 0 : void 0}
    left={xAxis === "left" ? 0 : void 0}
    position={"absolute"}
    width={isOpen ? expandedWidth : collapsedWidth}
    height={height}
    borderRadius={"$rounded12"}
    borderWidth={1}
    borderColor={isOpen ? "$accent1" : "$surface3"}
    focusStyle={{
      backgroundColor: "$surface1",
      borderColor: "$accent1"
    }}
    transition="all 200ms ease-in-out"
  >
        <Search
    fill={colors.neutral1.val}
    position={"absolute"}
    left={isOpen ? 10 : "50%"}
    top={"50%"}
    transform={isOpen ? "translate(0, -50%)" : "translate(-50%, -50%)"}
    size={20}
    pointerEvents="none"
  />
        <Input
    data-testid="animated-search-input"
    placeholder={placeholder}
    placeholderTextColor="$neutral3"
    autoComplete="off"
    pl={32}
    value={value}
    onChangeText={onChange}
    backgroundColor="$transparent"
    height="100%"
    width="100%"
    opacity={isOpen ? 1 : 0}
    color="$neutral2"
    textOverflow="ellipsis"
    onFocus={handleFocus}
    onBlur={handleBlur}
    $platform-web={{
      transitionDuration: "200ms",
      outline: "none",
      stroke: "none",
      border: "none"
    }}
    borderRadius={"$rounded12"}
  />

        <Flex
    opacity={isOpen ? 1 : 0}
    $platform-web={{ visibility: isOpen ? "visible" : "hidden" }}
    row
    centered
    position="absolute"
    right={6}
    top={"50%"}
    transform="translateY(-50%)"
    zIndex={zIndexes.mask}
  >
          <IconButton size="xxsmall" emphasis="secondary" onPress={handleClose} icon={<X />} p={3} scale={0.8} />
        </Flex>
      </Flex>
    </Flex>;
}
