"use strict";
import { PortfolioLogo } from "components/AccountDrawer/MiniPortfolio/PortfolioLogo";
import { AnimatePresence, motion } from "framer-motion";
import { useState } from "react";
import styled from "styled-components";
import { colors as themeColors } from "theme/colors";
import { Accordion, Flex, Separator, SpinningLoader, Text, styled as uiStyled } from "ui/src";
import { ChartBar } from "ui/src/components/icons/ChartBar";
import { RotatableChevron } from "ui/src/components/icons/RotatableChevron";
import { Sparkle } from "ui/src/components/icons/Sparkle";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { NumberType, useFormatter } from "utils/formatNumbers";
const RightSection = uiStyled(Flex, {
  width: 380,
  padding: "$spacing24",
  flexDirection: "column",
  backgroundColor: "$surface2Hovered",
  justifyContent: "flex-start",
  borderRadius: "$rounded16",
  cursor: "unset"
});
const ToggleContainer = uiStyled(Flex, {
  flexDirection: "row",
  backgroundColor: "$surface3",
  borderRadius: "$roundedFull",
  padding: 2,
  gap: 2,
  position: "relative"
});
const ToggleButton = uiStyled(Flex, {
  px: "$spacing12",
  py: "$spacing8",
  borderRadius: "$roundedFull",
  cursor: "pointer",
  justifyContent: "center",
  alignItems: "center",
  position: "relative",
  zIndex: 1,
  flexDirection: "row",
  gap: "$gap4"
});
const ActiveBackground = styled(motion.div)`
  position: absolute;
  inset: 0;
  height: 100%;
  width: 100%;
  background-color: ${themeColors.surface2_dark};
  border-radius: 9999px;
  z-index: 0;
`;
export function UserDepositRightContent({
  isExpanded,
  positions,
  netApy,
  isLoading,
  hasWallet
}) {
  const [activeTab, setActiveTab] = useState("apy");
  const { formatFiatPrice } = useFormatter();
  const chainId = UniverseChainId.Mainnet;
  const isApy = activeTab === "apy";
  const hasPositions = positions.length > 0;
  const netApyLabel = netApy !== void 0 ? `${netApy.toFixed(2)}` : "--";
  return <RightSection
    onPress={(e) => {
      e.stopPropagation();
    }}
  >
      <Flex flexDirection="row" justifyContent="space-between" alignItems="flex-start" mb="$spacing16">
        <Flex flexDirection="column">
          <Text variant="body3" color="$neutral2">
            {isApy ? "Net APY" : "Claimable Rewards"}
          </Text>
          <Flex flexDirection="row" alignItems="baseline" gap="$gap4">
            {isLoading ? <SpinningLoader size={16} /> : <>
                <Text
    variant="heading3"
    fontSize={24}
    color={isApy && netApy && netApy > 0 ? "$greenVibrant" : "$neutral1"}
  >
                  {isApy ? netApyLabel : "--"}
                </Text>
                {isApy && <Text variant="heading3" fontSize={24} color="$neutral3">
                    %
                  </Text>}
              </>}
          </Flex>
        </Flex>

        {
    /* Custom Toggle */
  }
        <ToggleContainer>
          <ToggleButton onPress={() => setActiveTab("apy")}>
            <AnimatePresence>
              {isApy && <ActiveBackground
    layoutId="earnToggle"
    transition={{ type: "spring", stiffness: 500, damping: 30 }}
  />}
            </AnimatePresence>
            <ChartBar color={isApy ? "$neutral1" : "$neutral3"} size={16} zIndex={2} />
            <Text variant="buttonLabel4" color={isApy ? "$neutral1" : "$neutral2"} zIndex={2}>
              APY
            </Text>
          </ToggleButton>
          <ToggleButton onPress={() => setActiveTab("rewards")}>
            <AnimatePresence>
              {!isApy && <ActiveBackground
    layoutId="earnToggle"
    transition={{ type: "spring", stiffness: 500, damping: 30 }}
  />}
            </AnimatePresence>
            <Sparkle color={!isApy ? "$neutral1" : "$neutral3"} size={16} zIndex={2} />
            <Text variant="buttonLabel4" color={!isApy ? "$neutral1" : "$neutral2"} zIndex={2}>
              Rewards
            </Text>
          </ToggleButton>
        </ToggleContainer>
      </Flex>

      <AnimatePresence initial={false} mode="wait">
        {isApy ? isExpanded && <motion.div
    key="apy-content"
    initial={{ height: 0, opacity: 0 }}
    animate={{ height: "auto", opacity: 1 }}
    exit={{ height: 0, opacity: 0 }}
    transition={{ duration: 0.3, ease: "easeInOut" }}
    style={{ overflow: "hidden" }}
  >
                <Flex flexDirection="column">
                  <Accordion type="multiple" defaultValue={["apy", "abx"]}>
                    {
    /* Native APY Accordion */
  }
                    <Flex>
                      <Accordion.Item value="apy">
                        <Accordion.Header>
                          <Accordion.Trigger width="100%" paddingVertical="$spacing12" backgroundColor="transparent">
                            {({ open }) => <Flex flexDirection="row" justifyContent="space-between" alignItems="center">
                                <Flex flexDirection="row" gap="$gap12" alignItems="center">
                                  <ChartBar color="$neutral3" size={16} />
                                  <Text variant="body2" color="$neutral1">
                                    Native APY
                                  </Text>
                                </Flex>
                                <Flex flexDirection="row" gap="$gap8" alignItems="center">
                                  <Text variant="body2" color={netApy && netApy > 0 ? "$greenVibrant" : "$neutral1"}>
                                    {isLoading ? "--" : netApy !== void 0 ? `${netApy.toFixed(2)}%` : "--"}
                                  </Text>
                                  <RotatableChevron
    direction={open ? "up" : "down"}
    color="$neutral2"
    width={16}
    height={16}
  />
                                </Flex>
                              </Flex>}
                          </Accordion.Trigger>
                        </Accordion.Header>
                        <Accordion.HeightAnimator animation="fast">
                          <Accordion.Content backgroundColor="transparent" animation="fast" exitStyle={{ opacity: 0 }}>
                            {hasPositions ? <Flex flexDirection="column" gap="$gap16">
                                {positions.map((position) => <Flex
    key={position.vaultAddress}
    flexDirection="row"
    justifyContent="space-between"
    alignItems="center"
  >
                                    <Flex flexDirection="row" gap="$gap12" alignItems="center">
                                      <PortfolioLogo
    chainId={chainId}
    tokenSymbol={position.assetSymbol}
    tokenName={position.assetSymbol}
    images={[getTokenLogoUrl(position.assetAddress)]}
    size={20}
  />
                                      <Text variant="body4" color="$neutral2">
                                        {position.vaultName}
                                      </Text>
                                    </Flex>
                                    <Flex flexDirection="row" gap="$gap8">
                                      <Text variant="body4" color="$neutral2">
                                        {position.tokenPriceUsd > 0 ? formatFiatPrice({
    price: position.depositUsd,
    type: NumberType.FiatTokenStats
  }) : "--"}
                                      </Text>
                                      <Text
    variant="body4"
    color={position.apy && position.apy > 0 ? "$greenVibrant" : "$neutral2"}
  >
                                        {position.apy !== void 0 ? `${position.apy.toFixed(2)}%` : "--"}
                                      </Text>
                                    </Flex>
                                  </Flex>)}
                              </Flex> : <Flex py="$spacing12" alignItems="center">
                                <Text variant="body3" color="$neutral2">
                                  {hasWallet ? "No vault positions yet." : "Connect wallet to view positions."}
                                </Text>
                              </Flex>}
                          </Accordion.Content>
                        </Accordion.HeightAnimator>
                      </Accordion.Item>
                    </Flex>

                    <Separator my="$spacing4" backgroundColor="$surface3" />

                    {
    /* abx Accordion */
  }
                    <Accordion.Item value="abx">
                      <Accordion.Header>
                        <Accordion.Trigger width="100%" paddingVertical="$spacing12" backgroundColor="transparent">
                          {({ open }) => <Flex flexDirection="row" justifyContent="space-between" alignItems="center">
                              <Flex flexDirection="row" gap="$gap12" alignItems="center">
                                <Sparkle color="$neutral3" size={16} />
                                <Text variant="body2" color="$neutral1">
                                  Rewards
                                </Text>
                              </Flex>
                              <Flex flexDirection="row" gap="$gap8" alignItems="center">
                                <Text variant="body2" color="$neutral1">
                                  --
                                </Text>
                                <RotatableChevron
    direction={open ? "up" : "down"}
    color="$neutral2"
    width={16}
    height={16}
  />
                              </Flex>
                            </Flex>}
                        </Accordion.Trigger>
                      </Accordion.Header>
                      <Accordion.HeightAnimator animation="fast">
                        <Accordion.Content
    pb="$spacing12"
    animation="fast"
    exitStyle={{ opacity: 0 }}
    backgroundColor="transparent"
  >
                          <Flex py="$spacing12">
                            <Text variant="body3" color="$neutral2">
                              Reward data is not available yet.
                            </Text>
                          </Flex>
                        </Accordion.Content>
                      </Accordion.HeightAnimator>
                    </Accordion.Item>
                  </Accordion>
                </Flex>
              </motion.div> : isExpanded && <motion.div
    key="rewards-content"
    initial={{ opacity: 0, scale: 0.95 }}
    animate={{ opacity: 1, scale: 1 }}
    exit={{ opacity: 0, scale: 0.95 }}
    transition={{ duration: 0.2 }}
    style={{ flex: 1, display: "flex" }}
  >
                <Flex flex={1} justifyContent="center" alignItems="center" px="$spacing32" py="$spacing48">
                  <Text variant="body3" color="$neutral2" textAlign="center">
                    Reward data is not available yet.
                  </Text>
                </Flex>
              </motion.div>}
      </AnimatePresence>
    </RightSection>;
}
