"use strict";
import { Flex, Text, styled, SpinningLoader } from "ui/src";
import { useMorphoProtocolStats } from "hooks/morpho";
import { UniverseChainId } from "uniswap/src/features/chains/types";
const BannerContainer = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  backgroundColor: "$surface2",
  borderRadius: "$rounded16",
  padding: "$spacing16",
  marginBottom: "$spacing24",
  gap: "$spacing24",
  flexWrap: "wrap",
  $md: {
    flexDirection: "column",
    alignItems: "flex-start",
    gap: "$spacing16"
  }
});
const StatItem = styled(Flex, {
  flexDirection: "column",
  gap: "$spacing4",
  flex: 1,
  minWidth: 120,
  $md: {
    width: "100%"
  }
});
export default function ProtocolStatsBanner({ chainId = UniverseChainId.Mainnet }) {
  const { data: stats, isLoading } = useMorphoProtocolStats(chainId);
  if (isLoading) {
    return <BannerContainer>
        <Flex centered width="100%" py="$spacing8">
          <SpinningLoader size={20} />
        </Flex>
      </BannerContainer>;
  }
  if (!stats) {
    return null;
  }
  return <BannerContainer>
      <StatItem>
        <Text variant="body3" color="$neutral2">
          Total Value Locked
        </Text>
        <Text variant="body1" color="$neutral1" fontWeight="600">
          {stats.formattedTVL}
        </Text>
      </StatItem>

      <StatItem>
        <Text variant="body3" color="$neutral2">
          Total Borrowed
        </Text>
        <Text variant="body1" color="$neutral1" fontWeight="600">
          {stats.formattedBorrow}
        </Text>
      </StatItem>

      <StatItem>
        <Text variant="body3" color="$neutral2">
          Total Deposits
        </Text>
        <Text variant="body1" color="$neutral1" fontWeight="600">
          {stats.formattedDeposit}
        </Text>
      </StatItem>

      <StatItem>
        <Text variant="body3" color="$neutral2">
          Utilization
        </Text>
        <Text variant="body1" color="$neutral1" fontWeight="600">
          {stats.utilization.toFixed(2)}%
        </Text>
      </StatItem>

      <StatItem>
        <Text variant="body3" color="$neutral2">
          Markets
        </Text>
        <Text variant="body1" color="$neutral1" fontWeight="600">
          {stats.totalPoolCount}
        </Text>
      </StatItem>
    </BannerContainer>;
}
