"use strict";
import ToggleLend from "components/ToggleLend";
import { useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { Flex } from "ui/src";
import Borrow from "./Borrow";
import Earn from "./Earn";
import LendFooter from "./components/LendFooter";
function LendPage() {
  const { tab } = useParams();
  const navigate = useNavigate();
  const activeTab = tab?.toLowerCase() === "earn" ? "Earn" : "Borrow";
  const handleTabChange = (newTab) => {
    navigate(`/lend/${newTab.toLowerCase()}`);
  };
  useEffect(() => {
    if (!tab) {
      navigate("/lend/borrow", { replace: true });
    }
  }, [tab, navigate]);
  return <Flex mt="$spacing48" width="100%">
      <ToggleLend activeTab={activeTab} setActiveTab={handleTabChange} />

      {activeTab === "Borrow" && <Borrow />}
      {activeTab === "Earn" && <Earn />}
      <LendFooter />
    </Flex>;
}
export default LendPage;
